import { EachMessagePayload } from "kafkajs";

// Minimal shape of the redis client used for the dedup set.
interface DedupStore {
  has(key: string): Promise<boolean>;
  add(key: string): Promise<void>;
}

// Minimal shape of a DB transaction handle.
interface DbTransaction {
  query(sql: string, params: unknown[]): Promise<void>;
  commit(): Promise<void>;
  rollback(): Promise<void>;
}

interface Db {
  beginTransaction(): Promise<DbTransaction>;
}

interface WalletCreditEvent {
  eventId: string;
  walletId: string;
  amountCents: number;
}

const PROCESSED_EVENTS_KEY = "processed_events";

export class WalletCreditConsumer {
  constructor(
    private readonly dedupStore: DedupStore,
    private readonly db: Db,
  ) {}

  /**
   * eachMessage handler for the wallet-credit topic. Kafka redelivers on
   * consumer restart / rebalance / ack timeout, so this must be safe to
   * run twice for the same message without double-crediting the wallet.
   */
  async handleMessage({ message }: EachMessagePayload): Promise<void> {
    if (!message.value) {
      return;
    }

    const event: WalletCreditEvent = JSON.parse(message.value.toString());
    const dedupKey = event.eventId;

    // Skip if we've already handled this event.
    const alreadyProcessed = await this.dedupStore.has(dedupKey);
    if (alreadyProcessed) {
      return;
    }

    // Claim the dedup key up front, before the effect is durable.
    await this.dedupStore.add(dedupKey);

    // Persist the actual effect afterwards, in a separate transaction.
    // If the process dies between the add() above and the commit()
    // below, dedupKey is already set but the credit was never applied.
    const tx = await this.db.beginTransaction();
    try {
      await this.persistWalletCredit(tx, event);
      await tx.commit();
    } catch (err) {
      await tx.rollback();
      throw err;
    }
  }

  private async persistWalletCredit(
    tx: DbTransaction,
    event: WalletCreditEvent,
  ): Promise<void> {
    await tx.query(
      "UPDATE wallets SET balance_cents = balance_cents + $1 WHERE id = $2",
      [event.amountCents, event.walletId],
    );
    await tx.query(
      "INSERT INTO wallet_ledger (event_id, wallet_id, amount_cents) VALUES ($1, $2, $3)",
      [event.eventId, event.walletId, event.amountCents],
    );
  }
}
